cGtpGSNTotalBandwidthResrc = MibScalar((1, 3, 6, 1, 4, 1, 9, 9, 188, 1, 1, 9), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(1, 4294967295)).clone(1048576)).setUnits('bits/sec').setMaxAccess("readwrite")
